class HeapObject:
    def __init__(self, number, pointers, data):
        self.number = number
        self.size = 1 + pointers + data
        self.fields = [None] * pointers
        self.roots = []
    def value(self, source):
        if source is None:
            return None
        return self.roots[source]
    def push(self, obj):
        self.retain(obj)
        self.roots.append(obj)
        if name == "PUSH":
            self.push(self.value(command.source))
        elif name == "LOAD":
            self.push(self.roots[command.slot].fields[command.field])
        elif name == "POP":
            for _ in range(command.count):
                self.release(self.roots.pop())
